def absent_index(values, upper):
    if isinstance(upper, bool) or not isinstance(upper, int):
        raise TypeError("upper must be an integer")
    if upper < 0:
        raise ValueError("upper must be non-negative")
    if not isinstance(values, list):
        raise TypeError("values must be a list")
    if len(values) != upper:
        raise ValueError("exactly one value must be absent")

    previous = -1
    for value in values:
        if isinstance(value, bool) or not isinstance(value, int):
            raise TypeError("values must contain integers")
        if value < 0 or value > upper:
            raise ValueError("value outside permitted range")
        if value <= previous:
            raise ValueError("values must be strictly increasing")
        previous = value

    low = 0
    high = len(values) - 1
    while low < high:
        middle = (low + high) // 2
        if values[middle] == middle:
            low = middle + 1
        else:
            high = middle
    return low

